      Center(child: LayoutBuilder(builder: (_, box) { final d = math.min(box.maxWidth * (compact ? .98 : .84), box.maxHeight * (compact ? .72 : .80)).toDouble(); return SizedBox.square(dimension: d, child: Stack(children: [CustomPaint(size: Size(d, d), painter: _Orbits(clock.value)), for (var i = 0; i < platforms.length; i++) _Node(platform: platforms[i], index: i, total: platforms.length, selected: selected == i, diameter: d, phase: clock.value, onTap: () => setState(() => selected = selected == i ? null : i), onOpen: () => enter(i)), const Center(child: IgnorePointer(child: _Core()))])); })),
      Positioned(left: compact ? 12 : 30, right: compact ? 12 : 30, bottom: compact ? 14 : 28, child: selected == null ? const Center(child: Text('1× CLICK FOCUS    2× CLICK ENTER PLATFORM', style: TextStyle(fontSize: 6.5, letterSpacing: 1.8, color: Color(0x55FFFFFF)))) : _Panel(platform: platforms[selected!], index: selected!, total: platforms.length, onClose: () => setState(() => selected = null), onOpen: () => enter(selected!))),
    ])));
  }
}
class GamePlatformGroup { final String name; final String subtitle; final List<GamePlatform> platforms; const GamePlatformGroup(this.name, this.subtitle, this.platforms); }
class GamePlatform { final String name; final List<int> externalPlatformIds; const GamePlatform(this.name, this.externalPlatformIds); }
class _Node extends StatelessWidget {
