}
class _World extends CustomPainter { final int seed; final bool selected; final double phase; const _World({required this.seed, required this.selected, required this.phase}); @override void paint(Canvas c, Size s) { final center = s.center(Offset.zero); final r = s.width * .36; final rect = Rect.fromCircle(center: center, radius: r); final base = Color([0xFF8B7A6D, 0xFF647B87, 0xFF8C927E, 0xFF7D6F83, 0xFF718A86][seed % 5]); c.drawCircle(center, r * 1.35, Paint()..shader = RadialGradient(colors: [const Color(0x448FA8B8), Colors.transparent]).createShader(Rect.fromCircle(center: center, radius: r * 1.35))); c.drawCircle(center, r, Paint()..shader = RadialGradient(center: const Alignment(-.42, -.5), colors: [base, base.withValues(alpha: .72), const Color(0xFF25303A), const Color(0xFF03050A)]).createShader(rect)); c.drawCircle(center, r, Paint()..style = PaintingStyle.stroke..strokeWidth = selected ? 1.3 : .7..color = const Color(0x709AAEBC)); if (selected) c.drawArc(Rect.fromCircle(center: center, radius: r * 1.2), phase * math.pi * 2, 1.2, false, Paint()..style = PaintingStyle.stroke..strokeWidth = 1..color = const Color(0x889FB7C5)); }
  @override bool shouldRepaint(covariant _World old) => old.seed != seed || old.selected != selected || old.phase != phase;
}
class _Orbits extends CustomPainter { final double phase; const _Orbits(this.phase); @override void paint(Canvas c, Size s) { final center = s.center(Offset.zero); for (var i = 0; i < 7; i++) { final r = s.shortestSide * (.18 + i * .052); c.drawOval(Rect.fromCenter(center: center, width: r * 2, height: r * 1.15), Paint()..style = PaintingStyle.stroke..strokeWidth = i == 6 ? .9 : .45..color = const Color(0x1F90A7B7)); } c.drawArc(Rect.fromCenter(center: center, width: s.width * .84, height: s.height * .48), phase * math.pi * 2, .65, false, Paint()..style = PaintingStyle.stroke..strokeWidth = 1.1..color = const Color(0x507F9AAC)); }
  @override bool shouldRepaint(covariant _Orbits old) => old.phase != phase;
}
class _Core extends StatelessWidget { const _Core(); @override Widget build(BuildContext context) => Container(width: 58, height: 58, decoration: const BoxDecoration(shape: BoxShape.circle, gradient: RadialGradient(colors: [Color(0xFFFFFFFF), Color(0xFFD4C4A4), Color(0xFF695A48), Color(0x00000000)], stops: [0, .2, .48, 1]), boxShadow: [BoxShadow(color: Color(0x668F7B5D), blurRadius: 30, spreadRadius: 8)])); }
class _Panel extends StatelessWidget { final GamePlatform platform; final int index, total; final VoidCallback onClose, onOpen; const _Panel({required this.platform, required this.index, required this.total, required this.onClose, required this.onOpen}); @override Widget build(BuildContext context) => Container(padding: const EdgeInsets.all(14), decoration: BoxDecoration(color: const Color(0xF2070B12), border: Border.all(color: const Color(0x527E98A9))), child: Row(children: [Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('PLATFORM WORLD / ${index + 1}/$total', style: const TextStyle(fontSize: 6.5, letterSpacing: 1.8, color: Color(0x62FFFFFF))), const SizedBox(height: 5), Text(platform.name, style: const TextStyle(fontSize: 16, letterSpacing: 2.8))])), TextButton(onPressed: onClose, child: const Text('×')), FilledButton(onPressed: onOpen, child: const Text('ENTER ARCHIVE'))])); }
class _Space extends CustomPainter { final double phase; const _Space(this.phase); @override void paint(Canvas c, Size s) { final r = Offset.zero & s; c.drawRect(r, Paint()..shader = const RadialGradient(colors: [Color(0xFF0C1420), Color(0xFF030711), Color(0xFF010207)]).createShader(r)); final rnd = math.Random(1188); for (var i = 0; i < 420; i++) { final p = Offset(rnd.nextDouble() * s.width, rnd.nextDouble() * s.height); c.drawCircle(p, .25 + rnd.nextDouble() * .7, Paint()..color = Colors.white.withValues(alpha: .025 + .1 * ((math.sin(phase * math.pi * 2 + i) + 1) / 2))); } } @override bool shouldRepaint(covariant _Space old) => old.phase != phase; }